# ── Export Worker ──────────────────────────────────────────────────────────────
class ExportWorker(QObject):
    progress_updated = pyqtSignal(int, str)
    finished         = pyqtSignal(int, int)
    log_msg          = pyqtSignal(str, str)

    def __init__(self, categories, destination_root):
        super().__init__()
        self.categories       = categories
        self.destination_root = destination_root

    def run(self):
        success_count = error_count = 0
        total_files = sum(len(cat.inputs) for cat in self.categories)
        if total_files == 0:
            self.finished.emit(0, 0); return
        self.log_msg.emit(f"Starting export of {total_files} files...", "INFO")
        for cat in self.categories:
            safe_name  = sanitize_folder_name(cat.display_name)
            target_dir = Path(self.destination_root) / safe_name
            try:
                os.makedirs(target_dir, exist_ok=True)
            except Exception as e:
                self.log_msg.emit(f"Could not create folder {safe_name}: {e}", "ERROR")
                error_count += len(cat.inputs); continue
            for inp in cat.inputs:
                src_path = inp.file_path
                if not src_path or not os.path.exists(src_path):
                    self.log_msg.emit(f"Skipping (not found): {inp.original_title}", "WARNING")
                    error_count += 1
                else:
                    try:
                        dest_path = target_dir / Path(src_path).name
                        self.progress_updated.emit(success_count + error_count, Path(src_path).name)
                        shutil.copy2(src_path, dest_path)
                        success_count += 1
                    except Exception as e:
                        self.log_msg.emit(f"Failed: {inp.original_title}: {e}", "ERROR")
                        error_count += 1
        self.finished.emit(success_count, error_count)


# ── Log Widget ─────────────────────────────────────────────────────────────────
class LogWidget(QTextEdit):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.setReadOnly(True)
        self.setMaximumHeight(130)
        self.setFont(F_MONO(10))

    def log(self, msg: str, level="INFO"):
        ts  = datetime.now().strftime("%H:%M:%S")
        col = {"INFO":C['text2'],"SUCCESS":C['accent'],"WARNING":C['warn'],"ERROR":C['dim']}.get(level, C['text2'])
        self.append(
            f'<span style="color:{C["dim2"]}">[{ts}]</span>&nbsp;'
            f'<span style="color:{col};font-weight:bold">{level}</span>'
            f'<span style="color:{C["text2"]}"> &mdash; {msg}</span>'
        )
        self.moveCursor(QTextCursor.MoveOperation.End)


# ── Export Widget ──────────────────────────────────────────────────────────────
class CategoryExportWidget(QWidget):
    def __init__(self, parent=None):
        super().__init__(parent)
        self.parser_ref = None
        self.thread = self.worker = None
        l = QVBoxLayout(self)
        l.setContentsMargins(22, 22, 22, 22); l.setSpacing(16)

        hdr = QLabel("Data Export")
        hdr.setStyleSheet(f"color:{C['text']}; font-family:Cambria; font-size:20px; font-weight:bold;")
        l.addWidget(hdr)

        sub = QLabel("Export modular category metadata (.xmlsmk) or backup physical media files to organized folders.")
        sub.setStyleSheet(f"color:{C['dim']}; font-family:Cambria; font-size:12px; font-style:italic;"); sub.setWordWrap(True)
        l.addWidget(sub)

        sep = QLabel(); sep.setFixedHeight(1); sep.setStyleSheet(f"background:{C['bd2']};")
        l.addWidget(sep)

        lbl1 = QLabel("Select categories to export:")
        lbl1.setFont(F(12, bold=True)); lbl1.setStyleSheet(f"color:{C['text2']};")
        l.addWidget(lbl1)

        self.cat_list = QListWidget()
        self.cat_list.setFont(F(12)); self.cat_list.setSelectionMode(QAbstractItemView.SelectionMode.MultiSelection)
        l.addWidget(self.cat_list)

        lbl2 = QLabel("Destination folder:")
        lbl2.setFont(F(12, bold=True)); lbl2.setStyleSheet(f"color:{C['text2']};")
        l.addWidget(lbl2)

        path_row = QHBoxLayout()
        self.dest_edit = QLineEdit()
        self.dest_edit.setFont(F(12)); self.dest_edit.setFixedHeight(40)
        self.dest_edit.setPlaceholderText("Select destination folder...")
        btn_browse = QPushButton("Browse...")
        btn_browse.setFont(F(12)); btn_browse.setFixedHeight(40)
        btn_browse.clicked.connect(self._browse_dest)
        path_row.addWidget(self.dest_edit); path_row.addWidget(btn_browse)
        l.addLayout(path_row)

        self.progress_bar = QProgressBar()
        self.progress_bar.setFixedHeight(10); self.progress_bar.setTextVisible(False)
        self.progress_bar.setStyleSheet(
            f"QProgressBar{{border:none;background:{C['bg3']};border-radius:2px;}}"
            f"QProgressBar::chunk{{background:{C['accent']};border-radius:2px;}}"
        )
        self.progress_bar.hide()
        l.addWidget(self.progress_bar)

        btn_row = QHBoxLayout(); btn_row.setSpacing(12)
        style_smk = (f"QPushButton{{background:{C['bg3']};color:{C['accent']};border:none;border-radius:3px;text-align:center;}}"
                     f"QPushButton:hover{{background:#3A3A5A;color:#FFFFFF;}}QPushButton:pressed{{background:#4A4A6A;}}")
        style_back = (f"QPushButton{{background:{C['bg3']};color:{C['text']};border:none;border-radius:3px;text-align:center;}}"
                      f"QPushButton:hover{{background:#3A3A5A;color:#FFFFFF;}}QPushButton:pressed{{background:#4A4A6A;}}")

        self.btn_smk_exp = QPushButton("Export Metadata (.xmlsmk)")
        self.btn_smk_exp.setFont(F(13, bold=True)); self.btn_smk_exp.setFixedHeight(48)
        self.btn_smk_exp.setStyleSheet(style_smk)
        self.btn_smk_exp.clicked.connect(self._export_smk)
        
        self.btn_files = QPushButton("Backup Assets")
        self.btn_files.setFont(F(11)); self.btn_files.setFixedHeight(48)
        self.btn_files.setStyleSheet(style_back)
        self.btn_files.clicked.connect(self._start_export)
        
        btn_row.addWidget(self.btn_smk_exp, 2); btn_row.addWidget(self.btn_files, 1)
        l.addLayout(btn_row)

    def refresh_categories(self, categories):
        self.cat_list.clear()
        for cat in sorted(categories.values(), key=lambda x: x.index):
            if cat.index == 0: continue
            item = QListWidgetItem(f"  [{cat.index:02d}]   {cat.display_name}   ({len(cat.inputs)} items)")
            item.setFont(F(12)); item.setData(Qt.ItemDataRole.UserRole, cat.index)
            self.cat_list.addItem(item)

    def _browse_dest(self):
        folder = QFileDialog.getExistingDirectory(self, "Select Destination Folder")
        if folder: self.dest_edit.setText(folder)

    def _export_smk(self):
        selected_items = self.cat_list.selectedItems()
        dest = self.dest_edit.text()
        if not selected_items:
            QMessageBox.warning(self, "Export", "Select at least one category."); return
        if not dest or not os.path.isdir(dest):
            QMessageBox.warning(self, "Export", "Select a valid destination folder."); return
        success_count = 0
        for item in selected_items:
            cat_idx = item.data(Qt.ItemDataRole.UserRole)
            if self.parser_ref.export_category_smk(cat_idx, dest):
                success_count += 1
        if success_count > 0:
            QMessageBox.information(self, "Export Complete", f"Successfully exported {success_count} category SMK files to:\n{dest}")

    def _start_export(self):
        selected_items = self.cat_list.selectedItems()
        dest = self.dest_edit.text()
        if not selected_items:
            QMessageBox.warning(self, "Export", "Please select at least one category."); return
        if not dest or not os.path.isdir(dest):
            QMessageBox.warning(self, "Export", "Please select a valid destination folder."); return
        selected_cats = [self.parser_ref.categories[i.data(Qt.ItemDataRole.UserRole)] for i in selected_items]
        total_files = sum(len(c.inputs) for c in selected_cats)
        if total_files == 0:
            QMessageBox.information(self, "Export", "Selected categories contain no files."); return
        
        self.btn_smk_exp.setEnabled(False); self.btn_files.setEnabled(False)
        self.progress_bar.setMaximum(total_files); self.progress_bar.setValue(0)
        self.progress_bar.show()
        
        self.thread = QThread()
        self.worker = ExportWorker(selected_cats, dest)
        self.worker.moveToThread(self.thread)
        self.thread.started.connect(self.worker.run)
        self.worker.progress_updated.connect(self._on_progress)
        self.worker.finished.connect(self._on_finished)
        self.worker.finished.connect(self.thread.quit)
        self.worker.finished.connect(self.worker.deleteLater)
        self.thread.finished.connect(self.thread.deleteLater)
        self.thread.start()

    def _on_progress(self, count, filename):
        self.progress_bar.setValue(count)

    def _on_finished(self, success, errors):
        self.btn_smk_exp.setEnabled(True); self.btn_files.setEnabled(True)
        self.progress_bar.setValue(self.progress_bar.maximum())
        msg = f"Backup Complete\n  Successfully copied : {success}\n  Failed / Missing   : {errors}"
        QMessageBox.information(self, "Export Finished", msg)


