class FolderImportWidget(QWidget):
    import_requested = pyqtSignal(list) # Emits list of (folder_name, sorted_files)

    def __init__(self, parent=None):
        super().__init__(parent)
        self.queue = []
        self.setAcceptDrops(True)
        l = QVBoxLayout(self)
        l.setContentsMargins(22, 22, 22, 22); l.setSpacing(16)

        hdr = QLabel("Folder Import")
        hdr.setStyleSheet(f"color:{C['text']}; font-family:Cambria; font-size:20px; font-weight:bold;")
        l.addWidget(hdr)

        sub = QLabel("Queue multiple folders. Each folder will create a Header Title followed by its media.")
        sub.setStyleSheet(f"color:{C['dim']}; font-family:Cambria; font-size:12px; font-style:italic;"); sub.setWordWrap(True)
        l.addWidget(sub)

        self.preview = QListWidget(); self.preview.setFont(F(12))
        l.addWidget(self.preview)

        btn_row = QHBoxLayout()
        style = (f"QPushButton{{background:{C['bg3']};color:{C['text']};border:none;border-radius:3px;text-align:center;}}"
                 f"QPushButton:hover{{background:#3A3A5A;color:#FFFFFF;}}QPushButton:pressed{{background:#4A4A6A;}}")
        style_imp = (f"QPushButton{{background:{C['bg3']};color:{C['accent']};border:none;border-radius:3px;text-align:center;}}"
                     f"QPushButton:hover{{background:#3A3A5A;color:#FFFFFF;}}QPushButton:pressed{{background:#4A4A6A;}}")

        btn_add = QPushButton("Add Folder to Queue")
        btn_add.setFixedHeight(40); btn_add.setStyleSheet(style)
        btn_add.clicked.connect(self._add_folder_to_queue)
        btn_clr = QPushButton("Clear Queue")
        btn_clr.setFixedHeight(40); btn_clr.setStyleSheet(style)
        btn_clr.clicked.connect(self._clear_queue)
        btn_row.addWidget(btn_add); btn_row.addWidget(btn_clr); btn_row.addStretch()
        l.addLayout(btn_row)

        self.btn_import = QPushButton("Start Bulk Import into Current Category")
        self.btn_import.setFont(F(14, bold=True)); self.btn_import.setFixedHeight(52)
        self.btn_import.setStyleSheet(style_imp)
        self.btn_import.clicked.connect(self._emit_import)
        l.addWidget(self.btn_import)

    def dragEnterEvent(self, event):
        if event.mimeData().hasUrls(): event.acceptProposedAction()

    def dragMoveEvent(self, event):
        if event.mimeData().hasUrls(): event.acceptProposedAction()

    def dropEvent(self, event):
        urls = event.mimeData().urls()
        added = 0
        for u in urls:
            path = u.toLocalFile()
            if path and os.path.isdir(path):
                p = Path(path)
                files = FileScanner.scan(path, recursive=False)
                files.sort()
                self.queue.append((p.name, files))
                self.preview.addItem(f"📁 {p.name} ({len(files)} files)")
                added += 1
        if added: event.acceptProposedAction()

    def _add_folder_to_queue(self):
        folder = QFileDialog.getExistingDirectory(self, "Select Folder")
        if folder:
            p = Path(folder)
            files = FileScanner.scan(folder, recursive=False)
            files.sort() # Ensure ascending order
            self.queue.append((p.name, files))
            self.preview.addItem(f"📁 {p.name} ({len(files)} files)")

    def _clear_queue(self):
        self.queue = []
        self.preview.clear()

    def _emit_import(self):
        if not self.queue:
            QMessageBox.warning(self, "Queue Empty", "Please add folders first.")
            return
        self.import_requested.emit(self.queue)
        self._clear_queue()


