        brand_icon.setContentsMargins(12, 0, 4, 0)
        brand_icon.setStyleSheet("background:transparent;border:none;")
        tb.addWidget(brand_icon)

        brand = QLabel("vMix Manager")
        # The line below is ignored by the system, you can keep or delete it:
        brand.setFont(F(20, bold=True)) 
        
        # --- UPDATE THIS LINE TO INCLUDE font-size AND font-weight ---
        brand.setStyleSheet(f"color:{C['text']}; letter-spacing:1px; background:transparent; font-size: 18px; font-weight: bold;")
        
        tb.addWidget(brand)
        tb.addWidget(QLabel("   "))

        rule = QWidget(); rule.setFixedSize(1, 28)
        rule.setStyleSheet(f"background:{C['bd2']};")
